def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 98:
        return 'C'

    last_my, last_opp = history[-1]

    total_opp_def = sum(1 for _, o in history if o == 'D')
    total_my_def = sum(1 for m, _ in history if m == 'D')

    if last_opp == 'D':
        if n >= 10 and total_opp_def * 100 <= n * 15 and total_my_def * 100 <= n * 15:
            return 'C'
        return 'D'

    my_def_count = 0
    opp_coop_after_my_def = 0
    opp_def_after_my_def = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            my_def_count += 1
            if history[i+1][1] == 'C':
                opp_coop_after_my_def += 1
            else:
                opp_def_after_my_def += 1

    if my_def_count == 0:
        if total_opp_def == 0 and n >= 10:
            if n == 10 or (n > 10 and n % 20 == 0):
                return 'D'
        return 'C'

    forgiveness = opp_coop_after_my_def - opp_def_after_my_def
    if forgiveness > 0:
        target_rate = 0.15
        allowed_def = int(target_rate * n)
        if my_def_count < allowed_def:
            return 'D'
        return 'C'
    else:
        return 'C'
